chorar.codigo:
async(ctx)=>{
  const{sock,jid,seloBot,mencoes,sender}=ctx;
  const alvo=mencoes[0]||sender;
  await sock.sendMessage(jid,{
    text:"😭 \n@"+alvo.split("@")[0]+" está a chorar!",
    mentions:[alvo]
  },{quoted:seloBot});
}

chamar.codigo:
async(ctx)=>{
  const{sock,jid,seloBot,isAdmin,isDono,args}=ctx; // <-- adicionei args aqui

  // 1. Só funciona em grupo
  if(!jid.endsWith("@g.us")){
    await sock.sendMessage(jid,{text:"❌ *Apenas em grupos.*"}, {quoted:seloBot});
    return;
  }

  // 2. Só admin/dono pode usar
  if(!isAdmin && !isDono){
    await sock.sendMessage(jid,{text:"❌ *Apenas administradores podem chamar!*"}, {quoted:seloBot});
    return;
  }

  try{
    // 3. Pega todos os membros do grupo
    const metadata = await sock.groupMetadata(jid);
    const membros = metadata.participants.map(p => p.id);

    // 4. Pega o motivo da chamada
    const motivo = args.join(' ') || 'Chamada de voz no grupo'; // <-- corrigido

    // 5. Monta a mensagem marcando todo mundo
    const texto = `📞 *CHAMADA DE VOZ INICIADA!* 📞\n\n*Motivo:* ${motivo}\n\n⚠️ *Entrem na chamada agora!*\nToquem no ícone de telefone aqui em cima 👆`;

    await sock.sendMessage(jid,{
      text: texto,
      mentions: membros // marca @todos
    }, {quoted:seloBot});

  }catch(e){
    await sock.sendMessage(jid,{text:`❌ *Erro ao chamar:* ${e.message}`}, {quoted:seloBot});
  }
}

